    # Validate key formats for early failure
    if deepseek_api_key and not deepseek_api_key.startswith("sk-"):
        print("[config] WARNING: DeepSeek API key does not start with 'sk-', may be invalid")
    if github_token and not github_token.startswith("github_pat_"):
        print("[config] WARNING: GitHub token format unexpected, may be invalid")
    return AppConfig(github_token=github_token, deepseek_api_key=deepseek_api_key)

