def _with_mock_fallback(mock_key: str):
    """Decorator that falls back to mock data on API failure."""
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            g = _get_github()
            if g is None:
                print(f"[github/client] No token -- using mock data")
                return _load_mock()[mock_key]
            try:
                return func(g, *args, **kwargs)
            except GithubException as e:
                print(f"[github/client] API error (HTTP {e.status}) -- falling back to mock data")
                return _load_mock()[mock_key]
        return wrapper
    return decorator
